//! The board insights and roll ranges against the upstream calculator's own
//! output.
//!
//! `fixtures/cog-insights.json` is generated by `script/cog-insights-oracle.mjs`
//! from `cog-optimizer.html` and `js/cogs/cog-judge.js` for the committed save,
//! so the marginal contributions, the replacement wording and the ranges are
//! compared field for field with the source of truth. The invariants that do not
//! need the fixture — the insight score is the optimizer's own score, and every
//! contribution is the score lost by removing its cog — are checked here too.

use idleon_core::cog::{
    Goal, Objective, OptimizeOptions, board_insights, compute_totals, goal_score, optimize,
    roll_ranges,
};
use idleon_core::model::Control;
use idleon_core::save::import;
use serde_json::Value;

fn fixture(path: &str) -> String {
    let path = format!("{}/{path}", env!("CARGO_MANIFEST_DIR"));
    std::fs::read_to_string(path).expect("the fixtures are committed")
}

fn save() -> idleon_core::cog::CogSave {
    import(&fixture("../../fixtures/data.json"))
        .expect("the fixture imports")
        .cog
}

fn oracle() -> Value {
    serde_json::from_str(&fixture("../../fixtures/cog-insights.json"))
        .expect("the oracle fixture parses")
}

fn number(value: &Value) -> f64 {
    value.as_f64().expect("a number")
}

fn text(value: &Value) -> String {
    value.as_str().expect("a string").to_string()
}

fn close(label: &str, got: f64, expected: f64) {
    let scale = expected.abs().max(1.0);
    assert!(
        (got - expected).abs() / scale < 1e-9,
        "{label}: got {got}, upstream {expected}"
    );
}

#[test]
fn the_effective_construction_level_matches_the_upstream_inference() {
    let oracle = oracle();
    let save = save();
    let expected = number(&oracle["constructionLevel"]) as u32;
    assert_eq!(save.construction_level, expected);
    assert_eq!(save.max_construction_level, expected);
}

#[test]
fn every_goal_insight_matches_the_upstream_calculator() {
    let oracle = oracle();
    let save = save();
    for goal in Goal::ALL {
        let expected = &oracle["goals"][goal.id()];
        let insights = board_insights(&save.board, goal)
            .unwrap_or_else(|| panic!("{}: the save board yields insights", goal.id()));
        close(
            "baseScore",
            insights.base_score,
            number(&expected["baseScore"]),
        );

        let impacts: Vec<_> = expected["impacts"]
            .as_array()
            .expect("impacts")
            .iter()
            .collect();
        assert_eq!(insights.impacts.len(), impacts.len(), "{}", goal.id());
        for (index, impact) in impacts.iter().enumerate() {
            let got = &insights.impacts[index];
            assert_eq!(got.slot as u64, impact["slot"].as_u64().expect("a slot"));
            close("delta", got.delta, number(&impact["delta"]));
            close("pct", got.pct, number(&impact["pct"]));
        }
        assert_eq!(
            insights.weakest.slot as u64,
            expected["weakest"]["slot"].as_u64().expect("a slot")
        );
        close(
            "weakest delta",
            insights.weakest.delta,
            number(&expected["weakest"]["delta"]),
        );
        assert_eq!(
            insights.best.slot as u64,
            expected["best"]["slot"].as_u64().expect("a slot")
        );
        close(
            "best delta",
            insights.best.delta,
            number(&expected["best"]["delta"]),
        );

        let targets = expected["rollTargets"].as_array().expect("targets");
        assert_eq!(insights.roll_targets.len(), targets.len(), "{}", goal.id());
        for (index, target) in targets.iter().enumerate() {
            let got = &insights.roll_targets[index];
            assert_eq!(got.slot as u64, target["slot"].as_u64().expect("a slot"));
            assert_eq!(got.col as u64, target["col"].as_u64().expect("a column"));
            assert_eq!(got.row as u64, target["row"].as_u64().expect("a row"));
            assert_eq!(got.why, text(&target["why"]), "{}", goal.id());
            assert_eq!(got.roll, text(&target["roll"]), "{}", goal.id());
            close("target pct", got.pct, number(&target["pct"]));
            close("target delta", got.delta, number(&target["delta"]));
        }
    }
}

#[test]
fn the_insight_score_is_the_optimizer_score() {
    let save = save();
    let options = OptimizeOptions {
        iterations: 10,
        ..OptimizeOptions::default()
    };
    for goal in Goal::ALL {
        let insights = board_insights(&save.board, goal).expect("insights");
        assert_eq!(insights.base_score, goal_score(&save.board, goal));
        // The optimizer measures the same board, so its starting score is the
        // insight's own; a result is never worse than it.
        let mut report = |_progress| Control::Continue;
        let objective = Objective::goal(goal);
        let result = optimize(&save.board, &save.shelf, &objective, &options, &mut report)
            .expect("a short run completes");
        assert_eq!(result.initial_score, insights.base_score, "{}", goal.id());
        assert!(result.score >= insights.base_score, "{}", goal.id());

        // Every contribution is the score lost by removing that cog, including
        // the surrounds it gave its neighbours.
        for impact in &insights.impacts {
            let mut without = save.board.clone();
            without[impact.slot] = None;
            let removed = goal_score(&without, goal);
            assert!(
                (insights.base_score - removed - impact.delta).abs() < 1e-9,
                "{}: slot {}",
                goal.id(),
                impact.slot
            );
        }
    }
}

#[test]
fn the_roll_ranges_match_the_upstream_calculator() {
    let oracle = oracle();
    let save = save();
    let level = save.max_construction_level;
    for goal in Goal::ALL {
        let expected = oracle["rollRanges"][goal.id()]
            .as_array()
            .expect("a range list");
        let ranges = roll_ranges(goal, level);
        assert_eq!(ranges.len(), expected.len(), "{}", goal.id());
        for (index, range) in expected.iter().enumerate() {
            let got = &ranges[index];
            let label = format!("{} tier {}", goal.id(), got.tier);
            assert_eq!(got.tier as u64, range["tier"].as_u64().expect("a tier"));
            assert_eq!(got.rolls as u64, range["rolls"].as_u64().expect("rolls"));
            close(&label, got.raw_magnitude, number(&range["rawMagnitude"]));
            close(&label, got.per_roll_min, number(&range["perRollMin"]));
            close(&label, got.per_roll_max, number(&range["perRollMax"]));
            close(&label, got.total_max, number(&range["totalMax"]));
            close(&label, got.min_surround, number(&range["minSurround"]));
            close(&label, got.max_surround, number(&range["maxSurround"]));
            assert_eq!(
                got.next_min_level as u64,
                range["nextMinLevel"].as_u64().expect("a level")
            );
            close(&label, got.next_min_value, number(&range["nextMinValue"]));
            assert_eq!(
                got.next_max_level as u64,
                range["nextMaxLevel"].as_u64().expect("a level")
            );
            close(&label, got.next_max_value, number(&range["nextMaxValue"]));
        }
    }
}

#[test]
fn the_ranges_follow_the_construction_level() {
    let save = save();
    assert!(
        save.max_construction_level > 100,
        "the fixture carries a high construction level"
    );
    let low = roll_ranges(Goal::ConExp, 100);
    let high = roll_ranges(Goal::ConExp, save.max_construction_level);
    for (low, high) in low.iter().zip(&high) {
        assert!(high.per_roll_max > low.per_roll_max, "tier {}", low.tier);
        assert!(high.total_max > low.total_max, "tier {}", low.tier);
        // The surround range is tier-fixed, not level-driven.
        assert_eq!(low.min_surround, high.min_surround);
        assert_eq!(low.max_surround, high.max_surround);
    }
    // The board's totals are unchanged by a range question.
    let totals = compute_totals(&save.board);
    assert!(totals.total_build > 0.0);
}
